targets.expr:
{service_name=~"${service:regex}",level=~"${level:regex}"}
| json | __error__=""
| label_format matches=`{{- $q := trim (urldecode "${search:percentencode}") -}}
{{- if hasPrefix "request_id:" $q -}}
  {{- $id := trimPrefix "request_id:" $q | trim -}}{{ and (ne $id "") (eq $id .request_id) }}
{{- else if hasPrefix "session_id:" $q -}}
  {{- $id := trimPrefix "session_id:" $q | trim -}}{{ and (ne $id "") (eq $id .session_id) }}
{{- else -}}
  {{- or (eq $q .request_id) (eq $q .session_id) (contains $q .message) (contains $q .operation) (contains $q .error_reason) -}}
{{- end -}}`
| matches="true" | drop matches, error_file, error_line, error_function
| label_format summary=`{{ .message }}{{ with .dependency }} · {{ . }}{{ end }}{{ with .upstream }} → {{ . }}{{ with $.upstream_status }} ({{ . }}){{ end }}{{ end }}{{ with .error_reason }}{{ if ne . $.message }} · {{ . }}{{ end }}{{ end }}{{ with .error_type }}{{ if ne . $.error_reason }} · {{ . }}{{ end }}{{ end }}{{ with .error_location }} · {{ . }}{{ end }}`
